AR=lambda n:''.join('٠١٢٣٤٥٦٧٨٩'[int(d)] for d in str(n))
def surah(name,ayat,cls="two tight"):
  ay=''.join((f'<p class="ay">{a.rsplit(" ",1)[0]} <span class="nw">{a.rsplit(" ",1)[1]}&nbsp;<i>{AR(k+1)}</i></span></p>' if ' ' in a else f'<p class="ay"><span class="nw">{a}&nbsp;<i>{AR(k+1)}</i></span></p>') for k,a in enumerate(ayat))
  return {"type":"raw","title":"أَحْفَظُ السُّورَةَ","html":f'<div class="surah fat {cls}"><h3>{name}</h3><p class="bas">بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ</p><div class="cols">{ay}</div></div>'}
